import {buildingLotMembers} from './building-lots.js?v=courtyard-apartments-1';
import {scenarioAllowsBackground} from './scenario-background-rules.js?v=courtyard-apartments-1';
import {recordHazard} from './emergency-order.js?v=courtyard-apartments-1';
import {beginEmergencySession} from './emergency-session.js?v=courtyard-apartments-1';
import {occupancy} from './utilities.js?v=courtyard-apartments-1';
export const freshToxicCloud=()=>({randomToxicClouds:false,toxicCloud:null,toxicClouds:0,toxicEvacuations:0});
export function startToxicCloud(c,x,y){const n=Math.sqrt(c.tiles.length),e=c.emergency;if(e.toxicCloud)return{ok:false,error:'This disaster type is already active.'};if(!Number.isInteger(x)||!Number.isInteger(y)||x<0||y<0||x>=n||y>=n)return{ok:false,error:'Choose a tile inside the city.'};const horizontal=Math.abs(x-n/2)>=Math.abs(y-n/2);beginEmergencySession(c);recordHazard(e,'toxicCloud');Object.assign(e,{toxicCloud:{x,y,age:0,dx:horizontal?(x<n/2?1:-1):0,dy:horizontal?0:(y<n/2?1:-1)}});e.toxicClouds++;return{ok:true};}
export function stepToxicCloud(c){const e=c.emergency,s=e.toxicCloud;if(!s)return;const n=Math.sqrt(c.tiles.length),affected=new Set();for(let i=0;i<c.tiles.length;i++){const t=c.tiles[i];if(Math.hypot(t.x-s.x,t.y-s.y)>2||!t.level||!['residential','commercial','industrial','airport','seaport'].includes(t.type))continue;if(t.lotRoot!=null){for(const u of buildingLotMembers(c,t))affected.add(u.y*n+u.x);}else if(t.farmRoot!==null&&t.farmRoot!==undefined){for(let j=0;j<c.tiles.length;j++)if(c.tiles[j].farmRoot===t.farmRoot)affected.add(j);}else if(t.facilityRoot!==null&&t.facilityRoot!==undefined){for(let j=0;j<c.tiles.length;j++)if(c.tiles[j].facilityRoot===t.facilityRoot)affected.add(j);}else affected.add(i);}
 for(const i of affected){const t=c.tiles[i];if(!t.level)continue;if(t.type==='residential')e.displaced+=occupancy(t.level)*8;e.toxicEvacuations++;if(['residential','commercial','industrial'].includes(t.type)){t.abandonedLevel=t.level;t.abandonmentCause='toxicCloud';}t.level=0;t.age=0;t.stress=0;}
 s.age++;if(s.age>=24){e.toxicCloud=null;return;}if(s.age%2===0){const x=s.x+s.dx,y=s.y+s.dy;if(x<0||y<0||x>=n||y>=n)e.toxicCloud=null;else{s.x=x;s.y=y;}}
}
export function validateToxicCloud(v,n,version){if(version<44)return freshToxicCloud();if(version>=45&&typeof v.randomToxicClouds!=='boolean')throw Error('Invalid random toxic cloud setting.');if(['toxicClouds','toxicEvacuations'].some(k=>!Number.isInteger(v[k])||v[k]<0||v[k]>1e9))throw Error('Invalid toxic cloud history.');let toxicCloud=null;if(v.toxicCloud!==null){const s=v.toxicCloud;if(!s||!v.active||(version<96&&(v.spaceJunk||v.riot||v.locust||v.tornado||v.earthquake))||!v.toxicClouds||!Number.isInteger(s.age)||s.age<0||s.age>=24||!Number.isInteger(s.dx)||!Number.isInteger(s.dy)||Math.abs(s.dx)+Math.abs(s.dy)!==1||['x','y'].some(k=>!Number.isInteger(s[k])||s[k]<0||s[k]>=n))throw Error('Invalid toxic cloud state.');toxicCloud={x:s.x,y:s.y,age:s.age,dx:s.dx,dy:s.dy};}return{randomToxicClouds:version>=45?v.randomToxicClouds:false,toxicCloud,toxicClouds:v.toxicClouds,toxicEvacuations:v.toxicEvacuations};}

export function toxicCloudSource(c){return c.tiles.filter(t=>(t.type==='toxicWaste'&&t.root===t.y*Math.sqrt(c.tiles.length)+t.x||t.type==='industrial'&&t.level>0&&t.industry==='dirty')&&!t.rubble&&!t.fire&&(t.airPollution||0)>50).sort((a,b)=>b.airPollution-a.airPollution)[0]||null;}
export function toxicCloudRisk(c){const source=toxicCloudSource(c);return source?.airPollution?Math.min(.03,(source.airPollution-50)*.0006):0;}
export function setRandomToxicClouds(c,value){if(c.emergency.active)return{ok:false,error:'Finish the active emergency before changing disaster settings.'};if(typeof value!=='boolean')return{ok:false,error:'Choose a valid toxic cloud setting.'};c.emergency.randomToxicClouds=value;return{ok:true};}
export function maybeToxicCloud(c){if(!scenarioAllowsBackground(c,'randomDisasters'))return false;if(!c.emergency.randomToxicClouds||c.emergency.active)return false;const risk=toxicCloudRisk(c);if(!risk)return false;let h=Math.imul(c.month+109,374761393)^Math.imul(c.seed+89,668265263);h=Math.imul(h^(h>>>13),1274126177);if(((h^(h>>>16))>>>0)/4294967296>=risk)return false;const t=toxicCloudSource(c);return startToxicCloud(c,t.x,t.y).ok;}
